// Slack은 view_submission payload를 application/x-www-form-urlencoded로 보냄.
// body.payload 안에 JSON 문자열이 들어있음.
const raw = $input.first().json.body || {};
const payload = typeof raw.payload === 'string' ? JSON.parse(raw.payload) : raw.payload;

if (!payload || payload.type !== 'view_submission') {
  // 다른 인터랙션(버튼 클릭 등)은 무시
  return [{ json: { skip: true } }];
}

const v = payload.view.state.values;
const get = (block, action = 'value') => v?.[block]?.[action];

const vendorName       = get('vendor_name')?.value || '';
const serviceName      = get('service_name')?.value || '';
const contractPurpose  = get('contract_purpose')?.value || '';
const contractStart    = get('contract_start')?.selected_date || null;
const contractEnd      = get('contract_end')?.selected_date || null;
const costRaw          = get('cost')?.value;
const cost             = costRaw ? Number(costRaw) : null;
const ownerUser        = get('owner_user')?.selected_user || '';
const extraUsersArr    = get('extra_notify_users')?.selected_users || [];
const renewalNotify    = get('renewal_notify_date')?.selected_date || null;
const vendorNotify     = get('vendor_notify_date')?.selected_date || null;

const registrantId     = payload.user.id;
const registrantName   = payload.user.name;

return [{
  json: {
    skip: false,
    vendor_name: vendorName,
    service_name: serviceName,
    contract_purpose: contractPurpose,
    contract_start: contractStart,
    contract_end: contractEnd,
    cost,
    owner_user_id: ownerUser,
    extra_user_ids: extraUsersArr.join(','),
    renewal_notify_date: renewalNotify,
    vendor_notify_date: vendorNotify,
    registrant_id: registrantId,
    registrant_name: registrantName
  }
}];

